{"files":[{"content":"#include <algorithm>
#include <iostream>
#include <vector>

using namespace std;

const int MOD = 1000000007;
const int CHUNKS = 4;

int main() {
    int n, m;
    if (!(cin >> n >> m)) return 0;

    vector<vector<int>> blockedCols(n);
    for (int c = 0; c < m; ++c) {
        int row, col;
        cin >> row >> col;
        blockedCols[row].push_back(col);
    }
    for (vector<int>& row : blockedCols) {
        sort(row.begin(), row.end());
    }

    vector<int> dp0(n, 0), dp1(n, 0);
    int pos = 0;
    const vector<int>& firstRow = blockedCols[0];
    for (int col = 0; col < n; ++col) {
        while (pos < static_cast<int>(firstRow.size()) && firstRow[pos] < col) ++pos;
        bool isBlocked = pos < static_cast<int>(firstRow.size()) && firstRow[pos] == col;
        if (isBlocked) {
            while (pos < static_cast<int>(firstRow.size()) && firstRow[pos] == col) ++pos;
            dp0[col] = 0;
        } else if (col == 0) {
            dp0[col] = 1;
        } else {
            dp0[col] = dp0[col - 1];
        }
    }

    int tails[CHUNKS] = {};
    int firstBlocked[CHUNKS] = {};
    int hasBlocked[CHUNKS] = {};

    #pragma omp parallel num_threads(4) if (n >= 1024) shared(blockedCols, dp0, dp1, tails, firstBlocked, hasBlocked, n)
    {
        for (int row = 1; row < n; ++row) {
            const int* previous = ((row - 1) & 1) ? dp1.data() : dp0.data();
            int* current = (row & 1) ? dp1.data() : dp0.data();

            #pragma omp for schedule(static) nowait
            for (int chunk = 0; chunk < CHUNKS; ++chunk) {
                int begin = n * chunk / CHUNKS;
                int end = n * (chunk + 1) / CHUNKS;
                const vector<int>& obstacles = blockedCols[row];
                auto it = lower_bound(obstacles.begin(), obstacles.end(), begin);
                size_t obstaclePos = static_cast<size_t>(it - obstacles.begin());

                int sum = 0;
                int first = end;
                int foundBlock = 0;
                for (int col = begin; col < end; ++col) {
                    if (obstaclePos < obstacles.size() && obstacles[obstaclePos] == col) {
                        foundBlock = 1;
                        if (first == end) first = col;
                        while (obstaclePos < obstacles.size() && obstacles[obstaclePos] == col) {
                            ++obstaclePos;
                        }
                        sum = 0;
                        current[col] = 0;
                    } else {
                        sum += previous[col];
                        if (sum >= MOD) sum -= MOD;
                        current[col] = sum;
                    }
                }
                tails[chunk] = sum;
                firstBlocked[chunk] = first;
                hasBlocked[chunk] = foundBlock;
            }

            #pragma omp barrier

            #pragma omp for schedule(static) nowait
            for (int chunk = 0; chunk < CHUNKS; ++chunk) {
                int lastReset = -1;
                for (int prior = 0; prior < chunk; ++prior) {
                    if (hasBlocked[prior]) lastReset = prior;
                }

                int carry = 0;
                int start = lastReset >= 0 ? lastReset : 0;
                for (int prior = start; prior < chunk; ++prior) {
                    carry += tails[prior];
                    if (carry >= MOD) carry -= MOD;
                }

                int begin = n * chunk / CHUNKS;
                for (int col = begin; col < firstBlocked[chunk]; ++col) {
                    current[col] += carry;
                    if (current[col] >= MOD) current[col] -= MOD;
                }
            }

            #pragma omp barrier
        }
    }

    cout << (((n - 1) & 1) ? dp1[n - 1] : dp0[n - 1]) << '\n';
    return 0;
}
